/* Interface de Devoluções; o banco autoriza cada consulta e alteração. */
(() => {
 'use strict';
 const R=window.DISB_RETURNS,G=window.DISB_RETURNS_GOOGLE,E=R.esc,$=id=>document.getElementById(id);
 const money=v=>v==null?'Não informado':(Number(v)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
 const num=v=>v==null?'—':Number(v).toLocaleString('pt-BR',{maximumFractionDigits:4});
 const pct=v=>v==null?'Sem base':(v*100).toLocaleString('pt-BR',{maximumFractionDigits:2})+'%';
 const goalPct=(value,goal)=>{const known=value!=null&&goal!=null,ok=known&&value<=goal+Number.EPSILON*8,label=value==null?'Sem base de rota':goal==null?'Meta não definida':(ok?'Dentro da meta':'Acima da meta')+' de '+pct(goal);return `<span class="rt-goal-result ${known?(ok?'rt-goal-ok':'rt-goal-over'):''}" title="${E(label)}" aria-label="${E(pct(value)+' · '+label)}"><strong>${E(pct(value))}</strong><small>${goal==null?'Sem meta':'Meta '+E(pct(goal))}</small></span>`;};
 const date=v=>v?String(v).slice(0,10).split('-').reverse().join('/'):'—';
 const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Fortaleza'}).format(new Date());
 const button=(a,label,extra='',primary=false)=>`<button type="button" class="btn ${primary?'primary':'secondary'}" data-rt-action="${a}" ${extra}>${label}</button>`;
 const options=(items,value,placeholder='Todos')=>`<option value="">${E(placeholder)}</option>`+items.map(x=>`<option value="${E(x.value??x)}" ${String(value)===String(x.value??x)?'selected':''}>${E(x.label??x)}</option>`).join('');
 const field=(label,name,value='',attrs='',type='input',origin='')=>`<label class="rt-field${origin?` rt-field-${origin}`:''}"><span>${label}${origin?`<small class="rt-field-origin">${origin==='auto'?'Automático':'Manual'}</small>`:''}</span>${type==='textarea'?`<textarea name="${name}" rows="3" maxlength="2000" ${attrs}>${E(value)}</textarea>`:`<input name="${name}" value="${E(value)}" ${attrs}>`}</label>`;
 const empty=message=>`<div class="rt-empty">${E(message)}</div>`;
 const panel=(title,body,detail='')=>`<section class="rt-panel"><header><h2>${E(title)}</h2>${detail?`<p>${E(detail)}</p>`:''}</header>${body}</section>`;
 const kpiIcon=label=>{const n=R.norm(label),paths=/valor|ticket/.test(n)?'<rect x="3" y="5" width="18" height="14" rx="3"/><circle cx="12" cy="12" r="3"/><path d="M7 9h.01M17 15h.01"/>':/volume|hl/.test(n)?'<path d="m12 3 9 5-9 5-9-5 9-5Z"/><path d="M3 8v9l9 5 9-5V8M12 13v9"/>':/entregues|rota/.test(n)?'<path d="M3 5h11v12H3zM14 9h4l3 4v4h-7"/><circle cx="7" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>':/pdv|cliente|vendedor/.test(n)?'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M21 21v-3a6 6 0 0 0-4-5"/>':/reversao|revertido|libera/.test(n)?'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>':/bloque/.test(n)?'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>':'<path d="M4 10h10a6 6 0 0 1 0 12M4 10l5-5M4 10l5 5"/>';return `<i class="rt-kpi-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${paths}</svg></i>`;};
 const card=(label,value,detail='',extra='')=>`<div class="rt-kpi ${E(extra)}">${kpiIcon(label)}<div class="rt-kpi-copy"><span>${E(label)}</span><strong>${E(value)}</strong>${detail?`<small>${E(detail)}</small>`:''}</div></div>`;
 const goalCard=(label,value,goal)=>{const known=value!=null&&goal!=null,ok=known&&value<=goal+Number.EPSILON*8;return card(label,pct(value),goal==null?'Meta não definida':'Meta '+pct(goal)+(known?' · '+(ok?'Dentro da meta':'Acima da meta'):''),known?(ok?'rt-goal-ok':'rt-goal-over'):'');};
 const status=s=>`<span class="rt-status rt-${E(s)}">${E(R.STATUS[s]||s)}</span>`;
 const responsibleLabels={MERCADO:'Mercado',LOGISTICA:'Logística',VENDAS:'Vendas',SEM_RESPONSAVEL:'Sem responsável'};
 function table(headers,rows,{page=0,size=100,paginate=false,className=''}={}){
  if(!rows.length)return empty('Nenhum registro para este filtro.');
  const start=paginate?page*size:0,selected=rows.slice(start,start+size);
  return `<div class="rt-table-wrap ${E(className)}" tabindex="0" role="region" aria-label="Tabela de devoluções"><table><thead><tr>${headers.map(h=>`<th scope="col">${E(h)}</th>`).join('')}</tr></thead><tbody>${selected.map(row=>`<tr>${row.map(c=>`<td>${c??'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${rows.length>size?`<div class="rt-pagination"><span>${start+1}–${Math.min(start+size,rows.length)} de ${num(rows.length)}</span>${paginate?button('previous','Anterior',page===0?'disabled':'')+button('next','Próxima',start+size>=rows.length?'disabled':''):'<span>As primeiras 100 linhas são exibidas. Use os filtros ou exporte os dados completos.</span>'}</div>`:''}`;
 }
 function bars(rows,metric='amount_cents'){
  if(!rows.length)return empty('Sem dados no período.');const top=[...rows].sort((a,b)=>b[metric]-a[metric]).slice(0,5),max=Math.max(...top.map(r=>r[metric]),1);
  return `<div class="rt-bars">${top.map(r=>`<div><span>${E(r.label)}</span><strong>${E(metric==='amount_cents'?money(r[metric]):num(r[metric])+' HL')}</strong><div class="rt-track"><i style="width:${Math.max(0,r[metric]/max*100)}%"></i></div></div>`).join('')}</div>`;
 }
 const shareOrder=rows=>[...rows].sort((a,b)=>(b.share??-1)-(a.share??-1)||b.outlets-a.outlets||b.amount_cents-a.amount_cents||String(a.label||a.customer_code).localeCompare(String(b.label||b.customer_code),'pt-BR',{numeric:true}));
 const ranking=rows=>table(['Nome','PDVs','Valor devolvido','Volume (HL)','Participação nos PDVs'],shareOrder(rows).map(r=>[E(r.label),num(r.outlets),money(r.amount_cents),num(r.volume_hl),pct(r.share)]));
 const trend=(rows,metric)=>{
  if(!rows.length)return empty('Sem dados no período.');const max=Math.max(...rows.map(r=>r[metric]),1);
  return `<div class="rt-trend" role="img" aria-label="Evolução diária; valores detalhados na tabela abaixo">${rows.map(r=>`<div title="${E(date(r.date)+': '+(metric==='amount_cents'?money(r[metric]):num(r[metric])+' HL'))}"><i style="height:${Math.max(1,r[metric]/max*100)}%"></i><small>${E(r.date.slice(8))}</small></div>`).join('')}</div><p class="rt-note">${date(rows[0].date)} a ${date(rows.at(-1).date)} · passe o cursor nas barras para ver o valor.</p>`;
 };
 const detailRows=rows=>rows.map(r=>[date(r.operation_date),E(r.map_number),E(r.customer_code),E(r.customer_name),E(R.cityLabel(r.city)||'Não informada'),money(r.amount_cents),num(r.volume_hl),E(R.reasonLabel(r.reason)),E(r.seller||'Não informado'),E(r.driver_treatment||'—')]);
 const detailHeaders=['Data','Mapa','PDV','Cliente','Cidade','Valor','HL','Motivo','Vendedor','Tratativa'];
 const messages=e=>{
  const s=String(e?.message||e||'Falha na operação.');
  if(/RETURN_VERSION_CONFLICT/.test(s))return 'Outra pessoa alterou esta devolução. Seus textos foram preservados. Abra o histórico e recarregue o registro antes de salvar.';
  if(/PENALTY_VERSION_CONFLICT/.test(s))return 'Este controle foi atualizado por outra pessoa ou pelo sistema. Confira os dados atualizados antes de tentar novamente.';
  if(/INVALID_PENALTY_TRANSITION/.test(s))return 'Essa mudança de status não está disponível. A liberação fica disponível quando o prazo terminar.';
  if(/INVALID_PENALTY_RULES/.test(s))return 'Preencha as seis penalidades com dias inteiros de 1 a 3650.';
  if(/FORBIDDEN|42501/.test(s))return 'Você não tem acesso a esta operação ou unidade. Confira as permissões de Devoluções.';
  if(/23505|duplicate key/.test(s))return 'Já existe uma devolução auditada para este cliente, data e mapa. Edite o registro existente.';
  if(/PGRST202|42P01|Could not find.*returns_/i.test(s))return 'O módulo aguarda a atualização do banco (migração 87).';
  if(/REDUCE_PERIOD/.test(s))return 'Há muitos registros neste período. Reduza as datas para consultar todos os dados.';
  if(/Failed to fetch|NetworkError|fetch/i.test(s))return 'Não foi possível conectar ao servidor. As alterações desta tela continuam disponíveis; tente novamente.';
  return s;
 };
 function create(adapter){
  const ctx=()=>adapter.context(),can=p=>adapter.hasPermission(p),key=()=>`${ctx().user?.id}|${ctx().unit}`;
  let identity='',generation=0,sequence=0,clock=null,channel=null,view='',snapshot=null,error='',loading=false,busy=false,dirty=false,editor=null,matches=[],page=0,updated=false,dashboardTab='returns-summary',syncing=false,syncState=null;
  let filter={from:today().slice(0,7)+'-01',to:today(),city:'',driver:'',reason:'',search:'',status:''};
  let goalMonth=today().slice(0,7),pendingStatus=null;
  let penaltyFilter={city:'',search:'',status:''},penaltyOperation=null,rulesDraft=null,reasonOwnerOperation=null,occurrenceModal=null,discardDraft=null,occurrenceRequest=0;
  const root=()=>$(`view-${view}`),notify=(m,t='success')=>adapter.toast(m,t);
  async function rpc(name,args){const {data,error}=await ctx().client.rpc(name,args);if(error)throw error;return data;}
  const args=()=>({p_unit:ctx().unit});
  const googleSources=G?.create({context:ctx,canSync:()=>can('RETURNS_IMPORT')&&can('RETURNS_VIEW'),imports:()=>snapshot?.imports||[],onStatus:state=>{syncState=state;if(snapshot)snapshot.google=state;if(view==='returns-import'&&!busy)render();else paintLive();}});
  function stop(){pendingStatus=null;penaltyOperation=null;rulesDraft=null;reasonOwnerOperation=null;occurrenceModal=null;discardDraft=null;occurrenceRequest++;penaltyFilter={city:'',search:'',status:''};googleSources?.stop();generation++;sequence++;clearInterval(clock);clock=null;if(channel){void ctx().client?.removeChannel(channel);channel=null;}identity='';snapshot=null;editor=null;dirty=false;busy=false;loading=false;error='';updated=false;syncing=false;syncState=null;for(const v of Object.keys(R.VIEWS)){const r=$('view-'+v);if(r)r.innerHTML='';}}
  function activateDashboardTab(tab){if(!R.FOLLOWUP_VIEWS.includes(tab))return false;dashboardTab=tab;page=0;return true;}
  function canLeave(){if(busy){notify('Aguarde a conclusão da operação.','error');return false;}if((dirty||discardDraft?.justification&&document.querySelector('[data-rt-discard-form]'))&&!confirm('Há alterações que ainda não foram salvas. Deseja sair desta tela?'))return false;dirty=false;editor=null;rulesDraft=null;discardDraft=null;return true;}
  function canChangeUnit(){return canLeave();}
  async function loadGoals(){const [result,rules,reasons]=await Promise.all([ctx().client.from('delivery_return_goals').select('month,outlet_rate,hl_rate,updated_at').eq('unit',ctx().unit).eq('month',goalMonth+'-01'),rpc('returns_penalty_rules',args()),rpc('returns_reason_catalog',args())]);if(result.error)throw result.error;return {goals:result.data||[],penalty_rules:rules,reason_catalog:reasons,at:new Date().toISOString()};}
  async function load(silent=false){
   if(!ctx().client||!ctx().user||!can('RETURNS_VIEW'))return;
   const request=++sequence,token=generation,unitKey=key();loading=true;if(!silent)render();
   try{const data=view==='returns-goals'?await loadGoals():view==='returns-penalties'?await rpc('returns_penalty_snapshot',args()):await rpc('returns_snapshot',{...args(),p_from:filter.from,p_to:filter.to});if(request!==sequence||token!==generation||unitKey!==key())return;snapshot=data;if(!syncing)syncState=data.google||null;error='';updated=!!editor||!!rulesDraft;}
   catch(e){if(request===sequence&&token===generation){error=messages(e);}}
   finally{if(request===sequence&&token===generation){loading=false;if(!editor&&!rulesDraft&&!busy)render();else paintLive();}}
  }
  function paintLive(){const el=root()?.querySelector('[data-rt-live]');if(el){const state=syncState||snapshot?.google;el.textContent=error||(updated?'Atualização recebida. O formulário aberto foi preservado.':syncing?'Atualizando as bases do Google Planilhas…':state?.last_error?'Google: '+state.last_error:state?.last_synced_at?'Google atualizado em '+new Date(state.last_synced_at).toLocaleString('pt-BR'):`Atualizado às ${snapshot?.at?new Date(snapshot.at).toLocaleTimeString('pt-BR'):'—'}`);el.classList.toggle('rt-error',!!(error||state?.last_error));}}
  async function updateGoogle(force=false){if(view==='returns-goals'||!googleSources||syncing||busy||!snapshot||!can('RETURNS_IMPORT')||globalThis.navigator?.onLine===false)return;const token=generation;syncing=true;paintLive();try{const result=await googleSources.sync({force});if(token===generation&&(result.changed||result.checkpoint))await load(true);}catch(e){if(token===generation){syncState={...syncState,last_error:messages(e)};if(force)notify(messages(e),'error');}}finally{if(token===generation){syncing=false;if(!editor&&!busy)render();else paintLive();}}}
  async function enter(next){
   if(identity!==key()){stop();identity=key();clock=setInterval(()=>{if(root()?.classList.contains('active')&&!busy){void load(true);void updateGoogle(false);}},30000);
    if(ctx().client?.channel){const updates=()=>{if(!busy)void load(true);};channel=ctx().client.channel('returns-'+ctx().user.id+'-'+ctx().unit).on('postgres_changes',{event:'*',schema:'public',table:'delivery_return_cases',filter:'unit=eq.'+ctx().unit},updates).on('postgres_changes',{event:'*',schema:'public',table:'delivery_return_penalties',filter:'unit=eq.'+ctx().unit},updates).subscribe();}
   }
   if(view!==next){editor=null;matches=[];dirty=false;page=0;}view=next;render();await load();void updateGoogle(false);
  }
  function filters(){if(view==='returns-penalties')return penaltyFilters();const reports=snapshot?.reports||[],unique=prop=>R.labels(reports,prop);
   return `<form class="rt-filters" data-rt-filter-form>${field('De','from',filter.from,'type="date" required')}${field('Até','to',filter.to,'type="date" required')}<label class="rt-field"><span>Cidade</span><select name="city">${options(unique('city'),R.norm(filter.city))}</select></label><label class="rt-field"><span>Motorista</span><select name="driver">${options(unique('driver'),R.norm(filter.driver))}</select></label><label class="rt-field"><span>Motivo</span><select name="reason">${options(unique('reason'),R.reasonKey(filter.reason))}</select></label>${field('Pesquisar','search',filter.search,'placeholder="PDV, mapa ou nome"')}${view==='returns-audited'?`<label class="rt-field"><span>Status</span><select name="status">${options(Object.entries(R.STATUS).map(([value,label])=>({value,label})),filter.status)}</select></label>`:''}<button class="btn primary" type="submit" ${busy?'disabled':''}>Aplicar</button>${button('clear-filter','Limpar')}</form>`;
  }
  function render(preserveFilter=true){const box=root();if(!box||!R.VIEWS[view])return;const oldFilter=preserveFilter&&box.querySelector('[data-rt-filter-form]'),draft=oldFilter?Object.fromEntries(new FormData(oldFilter)):null;box.classList.add('rt-workspace');const meta=R.VIEWS[view];
   const tabs=view==='returns-followup'?`<div class="fm-tabs rt-tabs" role="tablist" aria-label="Visões de acompanhamento">${R.FOLLOWUP_VIEWS.map(tab=>`<button type="button" role="tab" id="rt-tab-${tab}" aria-controls="rt-followup-panel" aria-selected="${tab===dashboardTab}" tabindex="${tab===dashboardTab?'0':'-1'}" class="${tab===dashboardTab?'active':''}" data-rt-action="tab" data-tab="${tab}">${E(R.VIEWS[tab][0])}</button>`).join('')}</div>`:'';
   box.innerHTML=`<div class="page-head"><div><div class="breadcrumb">Entrega / Devoluções</div><h1>${E(meta[0])}</h1><p>${E(meta[1])}</p></div><div class="rt-actions">${view==='returns-audited'&&can('RETURNS_EDIT')?button('new','＋ Cadastrar devolução','',true):''}${!['returns-import','returns-goals'].includes(view)?button('export','Exportar CSV'):''}${button('refresh','Atualizar',loading?'disabled':'')}</div></div><div class="rt-live" role="status" data-rt-live></div>${tabs}${view==='returns-import'?sourcesView():(editor||view==='returns-goals'?'':filters())+`<div data-rt-content ${view==='returns-followup'?`id="rt-followup-panel" role="tabpanel" aria-labelledby="rt-tab-${dashboardTab}"`:''}>${!snapshot?(loading?empty('Carregando dados da unidade…'):empty(error||'Não foi possível consultar os dados.')):content()}</div>`}`;
   if(draft)for(const [name,value] of Object.entries(draft)){const input=box.querySelector(`[data-rt-filter-form] [name="${name}"]`);if(input?.tagName==='SELECT'){for(const option of input.querySelectorAll('option'))option.selected=option.value===value;}else if(input)input.value=value;}
   paintLive();
  }
  function content(){
   if(view==='returns-goals')return goalsView();
   if(view==='returns-penalties')return penaltiesView();
   const mode=view==='returns-followup'?dashboardTab:view;
   const a=R.analytics(snapshot,filter),t=a.totals,kpis=`<div class="rt-kpis">${card('PDVs com devolução',num(t.outlets),'Cliente + mapa + data')}${card('Valor devolvido',money(t.amount_cents))}${card('Volume devolvido',num(t.volume_hl)+' HL')}${card('Ticket médio',money(t.outlets?t.amount_cents/t.outlets:null))}</div>`;
   const details=()=>panel('Devoluções do período',table(detailHeaders,detailRows(R.occurrences(a.rows)),{page,paginate:true}));
   if(view==='returns-audited')return auditView(a);
   if(mode==='returns-panel')return kpis+details();
   if(mode==='returns-city')return kpis+`<div class="rt-columns">${panel('Top 5 cidades por valor',bars(a.cities))}${panel('Top 5 cidades por volume',bars(a.cities,'volume_hl'))}</div>`+panel('Participação por cidade',ranking(a.cities),'Participação nos PDVs devolvidos do período; não é a taxa de devolução sobre as entregas da cidade.');
   if(mode==='returns-new-clients'){const n=a.newCustomers;return `<div class="rt-kpis">${card('Clientes novos com devolução',num(n.clients.length))}${card('Devoluções até 60 dias',num(n.totals.outlets))}${card('Valor devolvido',money(n.totals.amount_cents))}${card('Volume devolvido',num(n.totals.volume_hl)+' HL')}</div><p class="rt-note">Idade do cadastro na data da devolução: de 0 a 60 dias, inclusive. ${num(n.unknown)} devolução(ões) sem data de cadastro válida nos filtros atuais; essas ocorrências ficam fora deste recorte.</p>`+panel('Devoluções em clientes novos',table(['Data','Mapa','PDV / cliente','Cidade','Cadastro','Idade (dias)','Motivo da devolução','Valor','HL','Notas'],n.rows.map(r=>[date(r.operation_date),E(r.map_number),`<strong>${E(r.customer_code)} · ${E(r.customer_name)}</strong>`,E(R.cityLabel(r.city)),date(r.registration_date),num(R.registrationAge(r)),E(r.reason||'Não informado'),money(r.amount_cents),num(r.volume_hl),E(r.notes_display)]),{page,paginate:true}));}
   if(mode==='returns-clients')return `<div class="rt-kpis">${card('Clientes com devolução',num(a.clients.length))}${card('Devoluções registradas',num(t.outlets),'Cliente + mapa + data')}${card('Valor devolvido',money(t.amount_cents))}${card('Volume devolvido',num(t.volume_hl)+' HL')}</div>`+`<div class="rt-columns">${panel('Top 5 clientes por valor',bars(a.clients))}${panel('Top 5 clientes por volume',bars(a.clients,'volume_hl'))}</div>`+panel('Participação por cliente',table(['PDV / cliente','Cidade','Devoluções','Dias com devolução','Valor devolvido','Volume (HL)','Participação nas devoluções'],shareOrder(a.clients).map(r=>[`<strong>${E(r.customer_code)} · ${E(r.customer_name)}</strong>`,E(r.city||'Não informada'),num(r.outlets),num(r.days),money(r.amount_cents),num(r.volume_hl),pct(r.share)])),'Agrupa pelo código do cliente. Notas do mesmo mapa e dia contam como uma devolução; valores e volume incluem todas as notas.');
   if(mode==='returns-sellers')return `<div class="rt-kpis">${card('Vendedores com devolução',num(a.sellers.length))}${card('Devoluções registradas',num(t.outlets),'Cliente + mapa + data')}${card('Valor devolvido',money(t.amount_cents))}${card('Volume devolvido',num(t.volume_hl)+' HL')}</div>`+`<div class="rt-columns">${panel('Top 5 vendedores por valor',bars(a.sellers))}${panel('Top 5 vendedores por volume',bars(a.sellers,'volume_hl'))}</div>`+panel('Participação por vendedor',ranking(a.sellers),'Ordenado da maior para a menor participação nos PDVs devolvidos.');
   if(mode==='returns-team')return kpis+panel('Motoristas',ranking(a.drivers))+panel('Ajudantes',ranking(a.helpers),'Cada ajudante é contado uma vez por ocorrência. Não some os totais de ajudantes para obter o total da operação.');
   if(mode==='returns-reasons')return kpis+`<div class="rt-columns">${panel('Top 5 motivos por valor',bars(a.reasons))}${panel('Top 5 motivos por volume',bars(a.reasons,'volume_hl'))}</div>`+panel('Motivos do relatório',ranking(a.reasons))+panel('Motorista × cliente',table(['Motivo do motorista','Motivo do cliente','Casos'],a.reasonMatrix.map(r=>[E(r.driver),E(r.client),num(r.count)])),'Comparação dos registros auditados; justificativas não preenchidas aparecem como pendentes.')+`<div class="rt-columns">${panel('Motivos dos motoristas',ranking(a.driverReasons))}${panel('Motivos dos clientes',ranking(a.clientReasons))}</div>`;
   return kpis+`<div class="rt-kpis">${card('PDVs entregues no período',num(a.route.planned_outlets),'Total informado na base 17.03')}${card('HL entregues no período',num(a.route.planned_hl),'Total informado na base 17.03')}${goalCard('Devolução por PDV',a.route.outlet_rate,periodGoal(a,'outlet_rate','planned_outlets'))}${goalCard('Devolução por HL',a.route.hl_rate,periodGoal(a,'hl_rate','planned_hl'))}</div>`+
    (a.route.scoped?'<p class="rt-note">Os percentuais sobre a rota aparecem somente sem filtros de cidade, motorista, motivo ou pesquisa, pois a base 17.03 contém o total da unidade.</p>':a.route.missingDates.length||!a.route.days?'<p class="rt-note">Importe a base 17.03 para calcular percentuais. Dias de devolução sem total em rota: '+E(a.route.missingDates.map(date).join(', ')||'base ainda não importada')+'.</p>':'')+
    auditKpis(a,false)+`<div class="rt-columns">${panel('Evolução do valor devolvido',trend(a.daily,'amount_cents'))}${panel('Evolução do volume devolvido',trend(a.daily,'volume_hl'))}</div>`+panel('Evolução diária',table(['Data','PDVs em rota','PDVs devolvidos','HL em rota','HL devolvidos','% PDV','% HL','Valor'],a.daily.map(r=>[date(r.date),num(r.planned_outlets),num(r.outlets),num(r.planned_hl),num(r.volume_hl),goalPct(r.outlet_rate,monthGoal(r.date,'outlet_rate')),goalPct(r.hl_rate,monthGoal(r.date,'hl_rate')),money(r.amount_cents)])))+
    `<div class="rt-columns">${panel('Vendedores',ranking(a.sellers))}${panel('Dias da semana',ranking(a.weekdays))}</div>`+panel('Maiores devoluções',table(detailHeaders,detailRows(a.largest)));
  }
  function monthGoal(day,field){return (snapshot?.goals||[]).find(g=>String(g.month).slice(0,7)===day.slice(0,7))?.[field]??null;}
  function periodGoal(a,field,denominator){let weight=0,total=0;for(const day of a.daily){const n=Number(day[denominator]||0);if(n<=0)continue;const goal=monthGoal(day.date,field);if(goal==null)return null;weight+=n;total+=n*goal;}return weight?total/weight:null;}
  const auditKpis=(a,includePending=true)=>`<div class="rt-kpis rt-audit-kpis">${includePending?card('Aguardando repasse',num(a.counts.AGUARDANDO_REPASSE)):''}${card('Devolvido',num(a.counts.DEVOLVIDO))}${card('Devolução parcial',num(a.counts.PARCIAL))}${card('Revertido',num(a.counts.REVERTIDO))}${card('Reversão dos encerrados',pct(a.reversal_rate),`Sobre todos os casos: ${pct(a.reversal_all)}`)}</div>`;
  function statusControl(r){if(!can('RETURNS_EDIT'))return status(r.status);const value=pendingStatus?.id===r.id?pendingStatus.value:r.status;return `<label class="rt-status-control"><select class="rt-status-select" data-rt-status="${E(r.id)}" aria-label="Status da devolução do PDV ${E(r.customer_code)}" ${busy||editor?'disabled':''}>${Object.entries(R.STATUS).map(([v,label])=>`<option value="${v}" ${v===value?'selected':''}>${E(label)}</option>`).join('')}</select></label>`;}
  async function changeStatus(id,value){if(busy||editor||!can('RETURNS_EDIT')||!Object.hasOwn(R.STATUS,value))return;const row=snapshot?.cases?.find(r=>r.id===id);if(!row||row.status===value)return;const token=generation,unitKey=key(),payload={};for(const name of ['operation_date','customer_code','map_number','customer_name','city','branch','seller','driver','helper1','helper2','order_amount_cents','driver_reason','driver_treatment','client_reason','client_statement','status','is_drop'])payload[name]=row[name]??null;payload.status=value;pendingStatus={id,value};busy=true;render();
   try{const saved=await rpc('returns_save_case',{...args(),p_id:id,p_revision:row.revision,p_operation:crypto.randomUUID(),p_data:payload});if(token!==generation||unitKey!==key())return;Object.assign(row,saved||{},{status:value});notify('Status atualizado para '+R.STATUS[value]+'.');await load(true);}
   catch(e){if(token===generation&&unitKey===key()){notify(/RETURN_VERSION_CONFLICT/.test(String(e?.message||e))?'Outra pessoa alterou esta devolução. A lista foi atualizada; confira o status antes de tentar novamente.':messages(e),'error');await load(true);}}
   finally{if(token===generation&&unitKey===key()){pendingStatus=null;busy=false;render();}}
  }
  function auditView(a){return auditKpis(a)+(editor?editorView():'')+panel('Monitoramento em tempo real',table(['Data','PDV / cliente','Mapa / revenda','Cidade','Pedido','Vendedor','Motorista / ajudantes','Motivo do motorista','Tratativa do motorista','Auditoria da devolução','Status','Atualizado por','Ações'],a.audits.map(r=>[date(r.operation_date),`<strong>${E(r.customer_code)} · ${E(r.customer_name)}</strong>`,`${E(r.map_number||'Pendente')}<small>${E(r.branch||ctx().unit)}</small>`,E(r.city),money(r.order_amount_cents),E(r.seller),`${E(r.driver)}<small>${E([r.helper1,r.helper2].filter(Boolean).join(' / '))}</small>`,E(r.driver_reason),E(r.driver_treatment),`${E(r.client_reason)}<small>${E(r.client_statement)}</small>`,statusControl(r),`${E(r.updated_by_name)}<small>${E(new Date(r.updated_at).toLocaleString('pt-BR'))}</small>`,`<div class="rt-row-actions">${can('RETURNS_EDIT')?button('edit','Editar',`data-id="${E(r.id)}"`):''}${button('history','Histórico',`data-id="${E(r.id)}"`)}</div>`]),{page,paginate:true,className:'rt-audit-table'}));
  }
  function editorView(){const r=editor,automatic=new Set(['map_number','branch','city','customer_name','order_amount','seller','driver','helper1','helper2']);
   const entry=(label,name,value='',attrs='',type='input')=>field(label,name,value,attrs,type,automatic.has(name)?'auto':'manual');
   return `<section class="rt-panel rt-editor"><header><h2>${r.revision?'Editar devolução':'Cadastrar devolução'}</h2><p>Informe cliente e data para buscar o pedido e a equipe. As tratativas continuam editáveis depois de salvar.</p></header><form data-rt-case-form><div class="rt-field-legend" aria-label="Identificação dos campos"><span class="rt-legend-manual"><i aria-hidden="true"></i>Preenchimento manual</span><span class="rt-legend-auto"><i aria-hidden="true"></i>Automático · pode editar</span></div><div class="rt-grid">${entry('Código do cliente *','customer_code',r.customer_code,'required maxlength="40" inputmode="numeric"')}${entry('Data da entrega *','operation_date',r.operation_date,'type="date" required')}<div class="rt-field"><span>Dados do pedido</span>${button('lookup','Buscar informações')}</div></div>${matches.length>1?`<label class="rt-field rt-field-manual"><span>Selecione o mapa deste cliente/data *<small class="rt-field-origin">Manual</small></span><select data-rt-match><option value="">Escolha o mapa</option>${matches.map((m,i)=>`<option value="${i}">${E(m.map_number)} · ${money(m.order_amount_cents)}</option>`).join('')}</select></label>`:''}${r.lookupNote?`<p class="rt-note">${E(r.lookupNote)}</p>`:''}<div class="rt-grid">${entry('Mapa','map_number',r.map_number,'maxlength="40"')}${entry('Revenda','branch',r.branch,'maxlength="200"')}${entry('Cidade','city',r.city,'maxlength="200"')}${entry('Nome fantasia','customer_name',r.customer_name,'maxlength="200"')}${entry('Valor total do pedido','order_amount',r.order_amount_cents==null?'':(r.order_amount_cents/100).toFixed(2).replace('.',','),'inputmode="decimal" placeholder="Não informado"')}${entry('Vendedor','seller',r.seller,'maxlength="200"')}${entry('Motorista','driver',r.driver,'maxlength="200"')}${entry('Ajudante 1','helper1',r.helper1,'maxlength="200"')}${entry('Ajudante 2','helper2',r.helper2,'maxlength="200"')}</div><div class="rt-grid rt-two">${driverReasonField(r.driver_reason)}${entry('Motivo confirmado pelo cliente','client_reason',r.client_reason,'maxlength="200" placeholder="Ex.: preço, prazo ou pedido incorreto"')}${entry('Tratativa do motorista','driver_treatment',r.driver_treatment,'','textarea')}${entry('Auditoria da devolução','client_statement',r.client_statement,'placeholder="Relato do motorista ou do cliente"','textarea')}<label class="rt-field rt-field-manual"><span>Reversão / status *<small class="rt-field-origin">Manual</small></span><select name="status" required>${Object.entries(R.STATUS).map(([v,l])=>`<option value="${v}" ${r.status===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="rt-field rt-field-manual"><span>Entrega DROP<small class="rt-field-origin">Manual</small></span><select name="is_drop">${options([{value:'true',label:'Sim'},{value:'false',label:'Não'}],r.is_drop==null?'':String(r.is_drop),'Não classificada')}</select></label></div><p class="rt-note">Devolução parcial: o cliente devolveu parte das notas do pedido e ficou com pelo menos uma.</p><p class="rt-error" data-rt-case-error role="alert"></p><div class="rt-actions">${button('cancel','Cancelar')}<button class="btn primary" type="submit" ${busy?'disabled':''}>${busy?'Salvando…':'Salvar devolução'}</button></div></form></section>`;
  }
  function collect(form){const values=Object.fromEntries(new FormData(form));for(const name of ['customer_code','operation_date','map_number','branch','city','customer_name','seller','driver','helper1','helper2','driver_reason','driver_treatment','client_reason','client_statement','status'])editor[name]=R.text(values[name]);editor.order_amount_cents=values.order_amount===''?null:R.cents(values.order_amount);editor.is_drop=values.is_drop===''?null:values.is_drop==='true';return values;}
  function applyMatch(m){const preserve={driver_reason:editor.driver_reason,client_reason:editor.client_reason,driver_treatment:editor.driver_treatment,client_statement:editor.client_statement,status:editor.status};Object.assign(editor,m,preserve);editor.lookupKey=editor.customer_code+'|'+editor.operation_date;editor.lookupNote=m.order_amount_cents==null?'Nenhum pedido importado para este cliente/data. Confira e complete os dados disponíveis. Valores desconhecidos podem ficar em branco.':'';editor.operation=null;dirty=true;render();}
  async function lookup(){const form=root()?.querySelector('[data-rt-case-form]');collect(form);if(!editor.customer_code||!R.day(editor.operation_date))throw Error('Informe código do cliente e data válida.');const token=generation,owner=editor,idKey=key();busy=true;
   try{const data=await rpc('returns_lookup',{...args(),p_customer:editor.customer_code,p_date:editor.operation_date});if(token!==generation||owner!==editor||idKey!==key())return;matches=data||[];if(matches.length===1)applyMatch(matches[0]);else{editor.lookupNote='Há mais de um mapa. Escolha o mapa antes de salvar.';editor.lookupKey='';render();}}finally{busy=false;if(token===generation)render();}
  }
  async function saveCase(form){collect(form);const r=editor;if(r.lookupKey!==r.customer_code+'|'+r.operation_date)throw Error('Clique em Buscar informações para conferir o cliente e a data antes de salvar.');if(matches.length>1&&!r.lookupKey)throw Error('Selecione o mapa.');const amount=form.querySelector('[name="order_amount"]').value;if(amount!==''&&r.order_amount_cents===null)throw Error('Informe um valor válido para o pedido.');
   const payload={};for(const n of ['operation_date','customer_code','map_number','customer_name','city','branch','seller','driver','helper1','helper2','order_amount_cents','driver_reason','driver_treatment','client_reason','client_statement','status','is_drop'])payload[n]=r[n]??null;
   const fingerprint=JSON.stringify(payload);if(r.operationPayload!==fingerprint){r.operation=crypto.randomUUID();r.operationPayload=fingerprint;}const unitKey=key(),token=generation;busy=true;render();
   try{await rpc('returns_save_case',{...args(),p_id:r.id,p_revision:r.revision||0,p_operation:r.operation,p_data:payload});if(token!==generation||unitKey!==key())return;editor=null;dirty=false;matches=[];updated=false;notify('Devolução salva.');await load();}
   catch(e){if(token===generation){error=messages(e);throw e;}}
   finally{if(token===generation){busy=false;render();}}
  }
  async function history(id){const token=generation,unitKey=key();const {data,error}=await ctx().client.from('delivery_return_audit').select('*').eq('case_id',id).eq('unit',ctx().unit).order('created_at',{ascending:false}).limit(100);if(error)throw error;if(token!==generation||unitKey!==key())return;
   const keys={status:'Status',operation_date:'Data',customer_code:'PDV',map_number:'Mapa',customer_name:'Cliente',city:'Cidade',branch:'Revenda',seller:'Vendedor',driver:'Motorista',helper1:'Ajudante 1',helper2:'Ajudante 2',order_amount_cents:'Valor do pedido',driver_reason:'Motivo do motorista',driver_treatment:'Tratativa do motorista',client_reason:'Motivo do cliente',client_statement:'Auditoria da devolução',is_drop:'DROP'};
   const body=(data||[]).map(a=>{const old={...(a.previous?.data||{}),...a.previous},next={...(a.next?.data||{}),...a.next};return `<article class="rt-history"><strong>${E(a.actor_name)} · ${E(new Date(a.created_at).toLocaleString('pt-BR'))}</strong>${table(['Campo','Antes','Depois'],Object.entries(keys).filter(([k])=>old[k]!==next[k]).map(([k,l])=>[E(l),E(k==='status'?R.STATUS[old[k]]||'—':old[k]??'—'),E(k==='status'?R.STATUS[next[k]]:next[k]??'—')]))}</article>`;}).join('');
   adapter.modal({title:'Histórico da devolução',subtitle:'Alterações registradas pelo servidor',html:`<div class="rt-workspace">${body||empty('Nenhuma alteração disponível.')}</div>`});
  }
  function sourcesView(){
   const defs=G?.sources(ctx().unit)||[],state=syncState||snapshot?.google||{},labels={OK:'Atualizada',EMPTY:'Aguardando preenchimento',ERROR:'Confira a aba'};
   return panel('Bases da unidade',`<p class="rt-note">Preencha as abas de ${E(ctx().unit)} no Google Planilhas. As bases são verificadas ao abrir Devoluções e a cada 2 minutos enquanto esta área estiver aberta, para usuários com permissão de atualizar bases.</p><div class="rt-actions">${can('RETURNS_IMPORT')?button('sync-google',syncing?'Atualizando…':'Atualizar bases agora',syncing?'disabled':'',true):''}<a class="btn secondary" href="https://docs.google.com/spreadsheets/d/${G?.SPREADSHEET||''}/edit" target="_blank" rel="noopener">Abrir planilha</a></div><div class="rt-source-grid">${defs.map(source=>{const s=state.sources?.[source.kind];return `<article class="rt-source"><div><span class="rt-source-label">${E(source.label)}</span><strong>${E(source.title)}</strong><small>${E(s?labels[s.state]||'Aguardando atualização':'Aguardando atualização')}${s?.state==='OK'?` · ${num(s.count)} registros`:''}</small>${s?.message?`<p class="rt-error">${E(s.message)}</p>`:''}</div><a class="btn secondary" href="${E(source.url)}" target="_blank" rel="noopener">Preencher no Google ↗</a></article>`;}).join('')}</div><p class="rt-note">A aba MAPAS é preservada. Erros de preenchimento ou abas vazias mantêm a última base válida. Alterações nas linhas das bases Google aparecem na próxima atualização, sem alterar as tratativas e decisões da devolução auditada.</p>`)+panel('Últimas atualizações',table(['Quando','Base','Registros'],(snapshot?.imports||[]).filter(r=>r.filename.startsWith('Google Planilhas / ')).map(r=>[E(new Date(r.completed_at).toLocaleString('pt-BR')),E(G?.LABELS[r.kind]||(r.kind==='CUSTOMERS'?'Dados dos clientes':r.kind)),num(r.expected_rows)])));
  }
  function exportCSV(){if(!snapshot)return;if(view==='returns-penalties')return exportPenalties();if((view==='returns-followup'?dashboardTab:view)==='returns-sellers'){const a=R.analytics(snapshot,filter);return adapter.download(`Devolucoes-vendedores-${filter.from}-${filter.to}.csv`,new Blob([R.toCSV(['Vendedor','PDVs','Valor devolvido (R$)','HL','Participação (%)'],shareOrder(a.sellers).map(r=>[r.label,r.outlets,r.amount_cents/100,r.volume_hl,(r.share||0)*100]))],{type:'text/csv;charset=utf-8'}));}const a=R.analytics(snapshot,filter),audited=view==='returns-audited';if((view==='returns-followup'?dashboardTab:view)==='returns-new-clients')return adapter.download(`Devolucoes-clientes-novos-${filter.from}-${filter.to}.csv`,new Blob([R.toCSV(['Data','Mapa','PDV','Cliente','Cidade','Cadastro','Idade (dias)','Motivo da devolução','Valor (R$)','HL','Notas'],a.newCustomers.rows.map(r=>[date(r.operation_date),r.map_number,r.customer_code,r.customer_name,r.city,date(r.registration_date),R.registrationAge(r),r.reason||'Não informado',r.amount_cents/100,r.volume_hl,r.notes_display]))],{type:'text/csv;charset=utf-8'}));if((view==='returns-followup'?dashboardTab:view)==='returns-clients')return adapter.download(`Devolucoes-clientes-${filter.from}-${filter.to}.csv`,new Blob([R.toCSV(['PDV','Cliente','Cidade','Devoluções','Dias com devolução','Valor (R$)','HL','Participação (%)'],shareOrder(a.clients).map(r=>[r.customer_code,r.customer_name,r.city,r.outlets,r.days,r.amount_cents/100,r.volume_hl,(r.share||0)*100]))],{type:'text/csv;charset=utf-8'}));const headers=audited?['Data','PDV','Cliente','Mapa','Revenda','Cidade','Pedido (R$)','Vendedor','Motorista','Ajudante 1','Ajudante 2','Motivo motorista','Tratativa motorista','Motivo cliente','Auditoria da devolução','Status']:detailHeaders;
   const rows=audited?a.audits.map(r=>[date(r.operation_date),r.customer_code,r.customer_name,r.map_number,r.branch,r.city,r.order_amount_cents==null?'':r.order_amount_cents/100,r.seller,r.driver,r.helper1,r.helper2,r.driver_reason,r.driver_treatment,r.client_reason,r.client_statement,R.STATUS[r.status]]):R.occurrences(a.rows).map(r=>[date(r.operation_date),r.map_number,r.customer_code,r.customer_name,r.city,r.amount_cents/100,r.volume_hl,r.reason,r.seller,r.driver_treatment]);
   return adapter.download(`Devolucoes-${audited?'auditadas-':''}${filter.from}-${filter.to}.csv`,new Blob([R.toCSV(headers,rows)],{type:'text/csv;charset=utf-8'}));
  }
  function goalsView(){const goal=(snapshot?.goals||[]).find(g=>g.month.slice(0,7)===goalMonth);return panel('Metas de devolução',`<label class="rt-field"><span>Mês de referência</span><input type="month" data-rt-goal-month value="${E(goalMonth)}" required></label><div class="rt-kpis">${card('Meta de devolução por PDV',pct(goal?.outlet_rate))}${card('Meta de devolução por HL',pct(goal?.hl_rate))}</div><div class="rt-actions">${can('RETURNS_EDIT')?button('goal','Editar metas','',true):'<span class="rt-note">Você tem acesso de consulta às metas.</span>'}</div>`,'As metas são específicas da unidade selecionada e do mês. Informe os percentuais máximos de devolução por PDV e por HL.')+penaltyRulesView()+reasonOwnersView();}
  function penaltyRulesView(){const rules=rulesDraft?.rules||snapshot?.penalty_rules?.rules;if(!rules)return panel('Penalidades por recorrência',empty('Não foi possível carregar as penalidades. Atualize esta tela.'));
   return panel('Penalidades por recorrência',`<form data-rt-penalty-rules-form><div class="rt-grid rt-penalty-rules">${[2,3,4,5,6,7].map(n=>field(`${n===7?'7 ou mais':n} ocorrências · dias`,'days_'+n,rules[n],'type="number" min="1" max="3650" step="1" required '+(can('RETURNS_EDIT')?'':'disabled'))).join('')}</div><p class="rt-note">Contagem dos últimos 60 dias: notas do mesmo cliente, mapa e dia formam uma ocorrência. As regras são da unidade ${E(ctx().unit)} e independem do mês acima. Novos valores não alteram prazos de clientes já bloqueados.</p>${can('RETURNS_EDIT')?`<div class="rt-actions"><button class="btn primary" type="submit" ${busy?'disabled':''}>Salvar penalidades</button>${rulesDraft?button('cancel-rules','Descartar alterações'):''}</div>`:''}<p data-rt-rules-error class="rt-error" role="alert"></p></form>`,'Configure os dias de bloqueio para cada faixa de ocorrências.');
  }
  function driverReasonField(current=''){const byKey=new Map();for(const value of [...(snapshot?.reason_catalog||[]).map(r=>r.description),...(snapshot?.reports||[]).map(r=>r.reason),current]){const label=R.reasonLabel(value);if(label)byKey.set(R.reasonKey(label),label);}const selected=R.reasonKey(current),items=[...byKey].sort((a,b)=>a[1].localeCompare(b[1],'pt-BR'));return `<label class="rt-field rt-field-manual"><span>Motivo informado pelo motorista *<small class="rt-field-origin">Manual</small></span><select name="driver_reason" required><option value="">Selecione o motivo</option>${items.map(([key,label])=>`<option value="${E(label)}" ${key===selected?'selected':''}>${E(label)}</option>`).join('')}</select></label>`;}
  function reasonOwnersView(){const rows=Array.isArray(snapshot?.reason_catalog)?snapshot.reason_catalog:[];return panel('Responsáveis pelos motivos',`<p class="rt-note">Apenas Mercado conta para penalidade. Motivos novos aparecem como Sem responsável e não penalizam o cliente até serem classificados. A classificação é por código e pela unidade ${E(ctx().unit)}.</p>`+table(['Código','Motivo','Responsável','Atualizado por'],rows.map(r=>[E(r.reason_code||'—'),E(r.description),can('RETURNS_EDIT')?`<select class="rt-owner-select" data-rt-reason-owner="${E(r.reason_key)}" aria-label="Responsável pelo motivo ${E(r.description)}" ${busy?'disabled':''}>${Object.entries(responsibleLabels).map(([value,label])=>`<option value="${value}" ${r.responsible===value?'selected':''}>${E(label)}</option>`).join('')}</select>`:E(responsibleLabels[r.responsible]||'Sem responsável'),E(r.updated_by_name||'Sistema')]),{size:Math.max(100,rows.length)}));}
  async function changeReasonOwner(id,value){if(busy||!can('RETURNS_EDIT')||!Object.hasOwn(responsibleLabels,value))return;const row=snapshot?.reason_catalog?.find(r=>r.reason_key===id);if(!row||row.responsible===value)return;const token=generation,unitKey=key(),fingerprint=[unitKey,id,row.revision,value].join('|');if(reasonOwnerOperation?.fingerprint!==fingerprint)reasonOwnerOperation={fingerprint,id:crypto.randomUUID()};busy=true;render();try{await rpc('returns_set_reason_owner',{...args(),p_key:id,p_revision:row.revision,p_owner:value,p_operation:reasonOwnerOperation.id});if(token!==generation||unitKey!==key())return;reasonOwnerOperation=null;notify('Responsável atualizado. As recorrências foram recalculadas.');await load(true);}catch(e){if(token===generation&&unitKey===key()){notify(/REASON_VERSION_CONFLICT/.test(String(e?.message||e))?'Esse motivo foi alterado por outra pessoa. Confira o responsável atualizado.':messages(e),'error');await load(true);}}finally{if(token===generation&&unitKey===key()){busy=false;render();}}}
  async function penaltyOccurrences(id){const token=generation,unitKey=key(),request=++occurrenceRequest;const data=await rpc('returns_customer_occurrences',{...args(),p_id:id});if(token!==generation||unitKey!==key()||request!==occurrenceRequest)return;occurrenceModal={...data,identity:unitKey};discardDraft=null;renderOccurrenceModal();}
  function renderOccurrenceModal(){if(!occurrenceModal||occurrenceModal.identity!==key())return;const p=occurrenceModal.penalty,rows=R.occurrences(occurrenceModal.rows||[]);adapter.modal({title:'Ocorrências do cliente '+p.customer_code,subtitle:p.customer_name+' · '+date(p.window_from)+' a '+date(p.window_to),html:`<div class="rt-workspace rt-client-occurrences">${panel('Ocorrências e elegibilidade para penalidade',table(['Data','Mapa','Valor','HL','Motivo','Responsável','Contagem','Notas','Ações'],rows.map(r=>[date(r.operation_date),E(r.map_number),money(r.amount_cents),num(r.volume_hl),E(r.reason||'Não informado'),E((r.responsibles||[]).map(v=>responsibleLabels[v]||'Sem responsável').join(' / ')||'Sem responsável'),r.exclusion?`<span class="rt-status">Descartada</span><small>${E(r.exclusion.justification)}</small><small>${E(r.exclusion.created_by_name)} · ${E(penaltyTime(r.exclusion.created_at))}</small>`:r.penalty_eligible?'<span class="rt-status rt-penalty-BLOQUEAR">Conta para penalidade</span>':'<span class="rt-status">Não conta</span>',E(r.notes_display),can('RETURNS_EDIT')&&!r.exclusion?button('discard-occurrence','Descartar recorrência',`data-key="${E(r.row_key)}"`):'—']),{size:Math.max(100,rows.length)}),'Cada linha reúne as notas do mesmo cliente, mapa e dia. O descarte retira apenas a contagem para penalidade, mantendo o relatório fiscal e a justificativa.')}</div>`});}
  function openDiscard(keyValue){if(!can('RETURNS_EDIT')||occurrenceModal?.identity!==key())return;const row=R.occurrences(occurrenceModal.rows||[]).find(r=>r.row_key===keyValue);if(!row||row.exclusion)return;discardDraft={row,penalty:occurrenceModal.penalty,identity:key(),justification:'',operation:null};adapter.modal({title:'Descartar recorrência',subtitle:occurrenceModal.penalty.customer_name+' · '+date(row.operation_date)+' · Mapa '+row.map_number,html:`<form class="rt-workspace" data-rt-discard-form>${field('Justificativa obrigatória','justification','','required maxlength="2000"','textarea')}<p class="rt-note">As notas continuarão no relatório. Esta ocorrência deixará de contar para penalidade, e o descarte ficará registrado com seu nome e a justificativa.</p><p class="rt-error" data-rt-discard-error role="alert"></p><div class="rt-actions">${button('cancel-discard','Voltar')}<button class="btn primary" type="submit">Confirmar descarte</button></div></form>`});}
  async function saveDiscard(form){if(!discardDraft||discardDraft.identity!==key()||!can('RETURNS_EDIT'))return;const d=discardDraft,text=R.text(form.querySelector('[name=justification]').value);if(!text)throw Error('Informe a justificativa para descartar esta recorrência.');if(text.length>2000)throw Error('A justificativa deve ter até 2000 caracteres.');if(d.operationText!==text||!d.operation){d.operationText=text;d.operation=crypto.randomUUID();}d.justification=text;const token=generation,unitKey=key();busy=true;const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;try{await rpc('returns_discard_occurrence',{...args(),p_date:d.row.operation_date,p_customer:d.row.customer_code,p_map:d.row.map_number,p_justification:text,p_operation:d.operation});if(token!==generation||unitKey!==key())return;discardDraft=null;await load(true);await penaltyOccurrences(d.penalty.id);notify('Recorrência descartada com justificativa. A contagem foi recalculada.');}finally{if(token===generation&&unitKey===key()){busy=false;if(submit)submit.disabled=false;render();}}}
  function penaltyRows(){return (snapshot?.penalties||[]).filter(r=>(!penaltyFilter.status||r.status===penaltyFilter.status)&&(!penaltyFilter.city||R.norm(r.city)===R.norm(penaltyFilter.city))&&(!penaltyFilter.search||R.norm([r.customer_code,r.customer_name,r.city,r.seller].join(' ')).includes(R.norm(penaltyFilter.search))));}
  function penaltyFilters(){return `<form class="rt-filters" data-rt-filter-form><label class="rt-field"><span>Cidade</span><select name="city">${options(R.labels(snapshot?.penalties||[],'city'),R.norm(penaltyFilter.city))}</select></label><label class="rt-field"><span>Status</span><select name="status">${options(Object.entries(R.PENALTY_STATUS).map(([value,label])=>({value,label})),penaltyFilter.status)}</select></label>${field('Pesquisar','search',penaltyFilter.search,'placeholder="PDV, cliente, cidade ou vendedor"')}<button class="btn primary" type="submit" ${busy?'disabled':''}>Aplicar</button>${button('clear-filter','Limpar')}</form>`;}
  function penaltyControl(r){const next=r.status==='BLOQUEAR'?'BLOQUEADO':r.status==='LIBERAR'?'LIBERADO':null;if(!can('RETURNS_EDIT')||!next)return `<span class="rt-status rt-penalty-${E(r.status)}">${E(R.PENALTY_STATUS[r.status])}</span>`;return `<select class="rt-penalty-select rt-penalty-${E(r.status)}" data-rt-penalty-status="${E(r.id)}" aria-label="Status do bloqueio do PDV ${E(r.customer_code)}" ${busy?'disabled':''}>${Object.entries(R.PENALTY_STATUS).map(([value,label])=>`<option class="rt-penalty-${E(value)}" value="${value}" ${value===r.status?'selected':''} ${![r.status,next].includes(value)?'disabled':''}>${E(label)}</option>`).join('')}</select>`;}
  const penaltyTime=v=>v?new Date(v).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'short'}):'—';
  function penaltiesView(){const rows=penaltyRows(),remaining=r=>r.status==='BLOQUEADO'?Math.max(0,Math.ceil((Date.parse(r.release_at)-Date.parse(snapshot.at))/864e5)):0;
   return `<div class="rt-kpis">${Object.entries(R.PENALTY_STATUS).map(([s,label])=>card(label,num(rows.filter(r=>r.status===s).length))).join('')}</div>`+panel('Controle de bloqueios',table(['PDV / cliente','Cidade','Vendedor','Ocorrências','Penalidade','Status','Bloqueado em','Liberar em','Dias restantes','Ações'],rows.map(r=>[`<strong>${E(r.customer_code)} · ${E(r.customer_name)}</strong>`,E(R.cityLabel(r.city)||'Não informada'),E(r.seller||'Não informado'),`${num(r.eligible_occurrence_count??r.occurrence_count)}<small>${date(r.window_from)} a ${date(r.window_to)}</small>`,num(r.penalty_days)+' dias',penaltyControl(r)+(r.eligibility_note?`<small>${E(r.eligibility_note)}</small>`:''),E(penaltyTime(r.blocked_at)),E(penaltyTime(r.release_at)),r.status==='BLOQUEADO'?num(remaining(r)):'—',`<div class="rt-row-actions">${button('penalty-occurrences','Ver',`data-id="${E(r.id)}" aria-label="Ver ocorrências do PDV ${E(r.customer_code)}"`)}${button('penalty-history','Histórico',`data-id="${E(r.id)}"`)}</div>`]),{page,paginate:true,className:'rt-penalty-table'}),`Janela atual: ${date(snapshot.window_from)} a ${date(snapshot.window_to)}. Somente ocorrências atribuídas a Mercado entram na penalidade; descartes justificados não contam. Uma ocorrência por cliente, mapa e dia. Ao confirmar Bloqueado, a contagem e a penalidade ficam salvas e o prazo começa. O sistema muda para Liberar ao vencer o prazo; confirme Liberado pós bloqueio após realizar a liberação no sistema comercial.`);
  }
  async function changePenaltyStatus(id,value){if(busy||!can('RETURNS_EDIT'))return;const row=snapshot?.penalties?.find(r=>r.id===id);if(!row||row.status===value)return;const next=row.status==='BLOQUEAR'?'BLOQUEADO':row.status==='LIBERAR'?'LIBERADO':null;if(value!==next){render();return;}
   const message=value==='BLOQUEADO'?`Confirma que realizou o bloqueio do PDV ${row.customer_code}? O prazo de ${row.penalty_days} dias começa agora.`:`Confirma que realizou a liberação do PDV ${row.customer_code} no sistema comercial?`;if(!confirm(message)){render();return;}
   const token=generation,unitKey=key(),fingerprint=[ctx().unit,id,row.revision,value].join('|');if(penaltyOperation?.fingerprint!==fingerprint)penaltyOperation={fingerprint,id:crypto.randomUUID()};busy=true;render();
   try{await rpc('returns_set_penalty_status',{...args(),p_id:id,p_revision:row.revision,p_operation:penaltyOperation.id,p_status:value});if(token!==generation||unitKey!==key())return;penaltyOperation=null;notify('Status atualizado para '+R.PENALTY_STATUS[value]+'.');await load(true);}
   catch(e){if(token===generation&&unitKey===key()){notify(messages(e),'error');if(/PENALTY_VERSION_CONFLICT|INVALID_PENALTY_TRANSITION/.test(String(e?.message||e))){penaltyOperation=null;await load(true);}}}
   finally{if(token===generation&&unitKey===key()){busy=false;render();}}
  }

  async function penaltyHistory(id){const token=generation,unitKey=key(),{data,error}=await ctx().client.from('delivery_return_penalty_audit').select('event,actor_name,previous,next,created_at').eq('unit',ctx().unit).eq('penalty_id',id).order('id',{ascending:false}).limit(100);if(error)throw error;if(token!==generation||unitKey!==key())return;adapter.modal({title:'Histórico do bloqueio',subtitle:'Mudanças manuais e automáticas registradas pelo servidor',html:`<div class="rt-workspace">${table(['Quando','Responsável','Antes','Depois','Ocorrências','Penalidade','Prazo de liberação'],(data||[]).map(r=>[E(penaltyTime(r.created_at)),E(r.actor_name),E(R.PENALTY_STATUS[r.previous?.status]||'—'),E(R.PENALTY_STATUS[r.next?.status]||r.event),num(r.next?.occurrence_count),num(r.next?.penalty_days)+' dias',E(penaltyTime(r.next?.release_at))]))}</div>`});}
  function exportPenalties(){return adapter.download(`Bloqueios-recorrencia-${snapshot.window_to}.csv`,new Blob([R.toCSV(['PDV','Cliente','Cidade','Vendedor','Ocorrências','Início da janela','Fim da janela','Penalidade (dias)','Status','Bloqueado em','Liberar em','Liberado em'],penaltyRows().map(r=>[r.customer_code,r.customer_name,r.city,r.seller,r.occurrence_count,date(r.window_from),date(r.window_to),r.penalty_days,R.PENALTY_STATUS[r.status],penaltyTime(r.blocked_at),penaltyTime(r.release_at),penaltyTime(r.released_at)]))],{type:'text/csv;charset=utf-8'}));}
  function collectPenaltyRules(form){return Object.fromEntries([2,3,4,5,6,7].map(n=>[n,form.querySelector(`[name=days_${n}]`).value]));}
  async function savePenaltyRules(form){if(view!=='returns-goals'||!can('RETURNS_EDIT'))return;const rules=collectPenaltyRules(form);if(Object.values(rules).some(v=>!/^\d+$/.test(v)||Number(v)<1||Number(v)>3650))throw Error('Preencha os dias de penalidade com números inteiros de 1 a 3650.');const token=generation,unitKey=key(),revision=rulesDraft?.revision??snapshot.penalty_rules.revision;busy=true;
   try{await rpc('returns_save_penalty_rules',{...args(),p_revision:revision,p_rules:Object.fromEntries(Object.entries(rules).map(([k,v])=>[k,Number(v)]))});if(token!==generation||unitKey!==key())return;rulesDraft=null;dirty=false;notify('Penalidades atualizadas. Prazos de bloqueios em andamento foram preservados.');await load(true);}
   finally{if(token===generation&&unitKey===key()){busy=false;render();}}
  }
  async function goal(){if(view!=='returns-goals'||!can('RETURNS_EDIT'))return;const old=(snapshot.goals||[]).find(g=>g.month.slice(0,7)===goalMonth);adapter.modal({title:'Metas de devolução',subtitle:ctx().unit+' · '+goalMonth,html:`<form data-rt-goal-form class="rt-workspace"><input type="hidden" name="month" value="${E(goalMonth)}"><div class="rt-grid">${field('Meta de PDV (%)','outlet',old?.outlet_rate==null?'':num(old.outlet_rate*100),'inputmode="decimal"')}${field('Meta de HL (%)','hl',old?.hl_rate==null?'':num(old.hl_rate*100),'inputmode="decimal"')}</div><p>Deixe vazio se não houver meta definida.</p><button type="submit" class="btn primary">Salvar metas</button><p data-rt-goal-error class="rt-error" role="alert"></p></form>`});}
  document.addEventListener('click',async e=>{const b=e.target.closest('[data-rt-action]');if(!b||!b.closest('.rt-workspace')||busy||b.disabled)return;try{
   const action=b.dataset.rtAction;
   if(action==='tab'){if(activateDashboardTab(b.dataset.tab)){render();root()?.querySelector(`[data-tab="${dashboardTab}"]`)?.focus();}return;}
   if(action==='sync-google'){await updateGoogle(true);return;}
   if(action==='refresh'){await load();await updateGoogle(true);return;}
   if(action==='clear-filter'){if(view==='returns-penalties')penaltyFilter={city:'',search:'',status:''};else filter={from:today().slice(0,7)+'-01',to:today(),city:'',driver:'',reason:'',status:'',search:''};page=0;render(false);await load();return;}
   if(action==='cancel-rules'){rulesDraft=null;dirty=false;render();return;}
   if(action==='discard-occurrence'){openDiscard(b.dataset.key);return;}
   if(action==='cancel-discard'){discardDraft=null;renderOccurrenceModal();return;}
   if(action==='penalty-occurrences'){await penaltyOccurrences(b.dataset.id);return;}
   if(action==='penalty-history'){await penaltyHistory(b.dataset.id);return;}
   if(action==='new'||action==='edit'){if(!can('RETURNS_EDIT')||!canLeave())return;editor=action==='edit'?structuredClone(snapshot.cases.find(r=>r.id===b.dataset.id)):{id:crypto.randomUUID(),revision:0,operation_date:today(),customer_code:'',status:'AGUARDANDO_REPASSE',branch:ctx().unit};editor.lookupKey=editor.revision?editor.customer_code+'|'+editor.operation_date:'';matches=[];dirty=false;error='';render();root().querySelector('[data-rt-case-form] input')?.focus();return;}
   if(action==='cancel'){if(!canLeave())return;editor=null;dirty=false;updated=false;render();return;}
   if(action==='lookup'){await lookup();return;}
   if(action==='history'){await history(b.dataset.id);return;}
   if(action==='export'){await exportCSV();return;}
   if(action==='previous'||action==='next'){page=Math.max(0,page+(action==='next'?1:-1));render();return;}
   if(action==='goal')await goal();
  }catch(e){const message=messages(e);notify(message,'error');const el=root()?.querySelector('[data-rt-case-error],[data-rt-import-error]');if(el)el.textContent=message;}});
  document.addEventListener('input',e=>{if(e.target.closest('[data-rt-discard-form]')&&discardDraft)discardDraft.justification=e.target.value;if(e.target.closest('[data-rt-penalty-rules-form]')&&can('RETURNS_EDIT')){const form=e.target.closest('form');rulesDraft={rules:collectPenaltyRules(form),revision:rulesDraft?.revision??snapshot.penalty_rules.revision};dirty=true;}if(e.target.closest('[data-rt-case-form]')&&editor){collect(e.target.closest("form"));dirty=true;}});
  document.addEventListener('keydown',e=>{const b=e.target.closest('.rt-tabs [role="tab"]');if(!b||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=R.FOLLOWUP_VIEWS,at=tabs.indexOf(b.dataset.tab),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(at+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;activateDashboardTab(tabs[next]);render();root()?.querySelector(`[data-tab="${dashboardTab}"]`)?.focus();});
  document.addEventListener('change',async e=>{if(e.target.matches('[data-rt-reason-owner]')){await changeReasonOwner(e.target.dataset.rtReasonOwner,e.target.value);return;}if(e.target.matches('[data-rt-penalty-status]')){await changePenaltyStatus(e.target.dataset.rtPenaltyStatus,e.target.value);return;}if(e.target.matches('[data-rt-status]')){await changeStatus(e.target.dataset.rtStatus,e.target.value);return;}if(e.target.matches('[data-rt-goal-month]')){if(!/^\d{4}-\d{2}$/.test(e.target.value)||!R.day(e.target.value+'-01'))return;goalMonth=e.target.value;await load();return;}if(e.target.matches('[data-rt-match]')&&e.target.value!==''){const selected=matches[Number(e.target.value)];matches=[];applyMatch(selected);}});
  document.addEventListener('submit',async e=>{
   const form=e.target;if(!form.matches('[data-rt-filter-form],[data-rt-case-form],[data-rt-goal-form],[data-rt-penalty-rules-form],[data-rt-discard-form]'))return;e.preventDefault();if(busy)return;try{
    if(form.matches('[data-rt-discard-form]'))await saveDiscard(form);
    else if(form.matches('[data-rt-penalty-rules-form]'))await savePenaltyRules(form);
    else if(form.matches('[data-rt-filter-form]')){const f=Object.fromEntries(new FormData(form));if(view==='returns-penalties'){penaltyFilter={...penaltyFilter,...f};page=0;render();return;}if(!R.day(f.from)||!R.day(f.to)||f.to<f.from)throw Error('Confira as datas do período.');filter={...filter,...f};page=0;await load();}
    else if(form.matches('[data-rt-case-form]'))await saveCase(form);
    else{const values=Object.fromEntries(new FormData(form)),parse=v=>v===''?null:R.number(v);const outlet=parse(values.outlet),hl=parse(values.hl);if(!R.day(values.month+'-01'))throw Error('Confira o mês da meta.');if([outlet,hl].some(n=>n!=null&&(n<0||n>100))||values.outlet!==''&&outlet===null||values.hl!==''&&hl===null)throw Error('As metas devem estar entre 0 e 100%.');await rpc('returns_save_goal',{...args(),p_month:values.month+'-01',p_outlet:outlet==null?null:outlet/100,p_hl:hl==null?null:hl/100});adapter.closeModal();notify('Metas atualizadas.');await load();}
   }catch(e){const message=messages(e),el=document.querySelector('[data-rt-discard-error],[data-rt-case-error],[data-rt-goal-error],[data-rt-rules-error]');if(el)el.textContent=message;notify(message,'error');}
  });
  window.addEventListener('focus',()=>{if(root()?.classList.contains('active')&&!busy){void load(true);void updateGoogle(false);}});
  window.addEventListener('online',()=>{if(root()?.classList.contains('active')&&!busy){void load(true);void updateGoogle(false);}});
  window.addEventListener('beforeunload',e=>{if(dirty||busy||discardDraft?.justification&&document.querySelector('[data-rt-discard-form]')){e.preventDefault();e.returnValue='';}});
  return {enter,stop,canChangeUnit,canLeave,activateDashboardTab:tab=>{const changed=activateDashboardTab(tab);if(changed&&view==='returns-followup')render();return changed;}};
 }
 window.DISB_RETURNS_UI={create};
})();
